"""Inspected passages and bounded retrieval failures for the MGR workbook."""
ASOF = '2026-10-25'
sources, retrievals = [], []
def src(n,title,author,url,date,kind,locator,passage,note='',status='Passage inspected',origin=None,method='web.run passage inspection'):
    sid=f'S{n:03d}'
    sources.append({'Source ID':sid,'Title':title,'Author / institution':author,'Publication date':date,'URL':url,'Access date':ASOF,'Source class':kind,'Primary / secondary':'Primary' if kind in ('Official record','Legislative record','Court record','Primary statement','Commission record') else 'Secondary','Access status':status,'Origin ID':origin or sid,'Locator':locator,'Reliability / limitation':note or 'Supports the identified record, not sole personal causation or an independent impact estimate.'})
    retrievals.append({'id':f'R{n:03d}','source_id':sid,'url_or_query':url,'access_date':ASOF,'route':'Canonical page or explicitly identified reproduction','access_status':status,'origin_id':origin or sid,'locator':locator,'passage_paraphrase':passage,'method':method,'result':'Relevant passage inspected' if status=='Passage inspected' else note,'next_action':'Revisit only for new evidence or a better retrieval route.'})

src(1,'About MGR','Tamil Nadu Dr. M.G.R. Medical University; text courtesy Government of Tamil Nadu','https://www.tnmgrmu.ac.in/about-mgr/',None,'Official record','Biographical paragraphs, retrieved lines 83–90','Born 17 January 1917 in Kandy, Ceylon; parents Gopalan and Satyabhama. Family settled in Kumbakonam after father’s death; primary schooling and theatre preceded cinema. Joined DMK in 1953; Legislative Council in 1962; Assembly wins in 1967, 1971, 1977, 1980 and 1984. Founded party in 1972; CM from 1977; died 24 December 1987; posthumous Bharat Ratna.','Commemorative biography. Its uninterrupted-tenure language omits President’s Rule in 1980; medical-university founding is separated from actual operation in S011. Birth locality is retained at broad Ceylon level because summaries vary.')
src(2,'Birth centenary of MGR: 100 years','Adrija Roychowdhury, Indian Express','https://indianexpress.com/article/research/mgr-aiadmk-birth-centenary-of-mgr-100-years-tamil-nadu/','2017-01-17','Journalism','Career narrative, lines 25–40','Film debut Sathi Leelavathi in 1936; DMK from 1953; Council from 1962; MLA in 1967; treasurer after Annadurai. Anti-corruption dispute and expulsion in 1972 preceded ADMK formation. Three consecutive Assembly poll victories; Jayalalithaa entered party in 1982; succession split between Janaki and Jayalalithaa.','Article contains loose chronology, including a conflicting four-versus-three tenure phrase and a film-credit error. Those claims are not adopted. Succession description is used at broad level.')
src(3,'Noon Meal Programme','Pudukkottai district, Government of Tamil Nadu','https://pudukkottai.nic.in/noon-meal-programme/',None,'Official record','Programme history, lines 90–108','MGR launched the expanded programme on 1 July 1982 at Pappakurichi in Tiruchirappalli district; urban extension on 15 September 1982. Objectives include nutrition, enrolment and reduced dropouts. Education Department administered it from 1982 to May 1990.','Current menus and later eligibility changes are not backdated to MGR. Administrative objectives are not measured outcomes.')
src(4,'Livelihood Assessment Report','Institute of Development Alternatives; Tamil Nadu rural-development archive','https://tnrd.tn.gov.in/externallyaidedprojects/livelihood_ida.pdf','2004-12','Institutional research','Section 4.1.3, printed pp.46–49; PDF pp.64–67; lines 2174–2265','1982 scheme initially covered rural children aged 2–5 and 5–9, urban areas from September 1982, pensioners from January 1983, students aged 10–15 from September 1984. Report cites improved enrolment/retention, girls’ participation, and women’s employment. It warns that inconsistent data prevent attribution of enrolment growth specifically to meals; monitoring is weak and workers lack regular scales/security.','Retrospective 2004 assessment incorporating an MIDS study. Later staffing and nutrition statistics are not measurements of MGR’s tenure. Pregnancy coverage began in 1995, after his death.')
src(5,'Ethnicity and Pluralism: An Exploration with Reference to Indian Cases','Narendra Subramanian, Canadian Journal of Political Science 32(4), 715–744','https://nsubramanian.wordpress.com/wp-content/uploads/2009/11/ethnicityandpluralism.pdf','1999-12','Scholarship','AIADMK/DMK comparison; PDF pp.11–12, retrieved lines 781–920','Distinguishes assertive and paternalist populism. AIADMK promised protection to women and poor people, with meals an important benefit. Fan clubs provided a base after the DMK split. Supporters could pressure leaders, including on quotas. MGR’s non-Tamil origins did not preclude belonging through Tamil popular culture; Tamil and Indian identities could coexist.','Author-hosted scholarly article. Interpretive model, not a poll of every supporter or proof that welfare recipients lacked agency. Avoid treating the categories as immutable labels.')
src(6,'Review of the Eighth Tamil Nadu Legislative Assembly, 1985–1988','Tamil Nadu Legislative Assembly Secretariat; Paperzz reproduction','https://paperzz.com/doc/6805213/review-1985-88---tamil-nadu-legislative-assembly','1988','Legislative record','Printed pp.5–6, 13–15, 85–86; Council abolition appendix; retrieved lines 166–190,503–504,663–740,3407–3445,5821–5826','Sixth Assembly constituted 30 June 1977 after delimitation based on 1971 census; dissolved 17 February 1980. Seventh constituted 9 June 1980; eighth 16 January 1985 after December 1984 poll. MGR sworn on 10 February 1985; died 24 December 1987. Eight women elected in 1984, five AIADMK and three Congress. Gomathi Srinivasan held welfare/meals; Vijayalakshmi Palanisamy Khadi/handlooms. Editor imprisoned 4 April 1987, released 6 April after recorded MGR request. Council abolished 1 November 1986.','Official-origin text on a third-party host because original Assembly archive timed out. OCR needs caution. Assembly narrative praises MGR’s release intervention; court S008 independently establishes constitutional violation.',origin='TN-ASSEMBLY-REVIEW8')
src(7,'D. Jayaraman v. Government of Tamil Nadu','Madras High Court; Indian Kanoon reproduction','https://indiankanoon.org/doc/280649/','1986-07-21','Court record','Paras 1–26; especially voting account and final dismissal','Petitioner challenged 14 May 1986 resolution to abolish Legislative Council, alleging political motives. Resolution had 136 votes for and 25 against; 61 members withdrew. Court rejected the challenge and upheld the resolution’s validity.','Challenge to Assembly resolution, not a criminal proceeding or judicial endorsement of political wisdom. Abolition itself required parliamentary legislation and later commencement.')
src(8,'S. Balasubramanian v. State of Tamil Nadu','Madras High Court, Full Bench; Indian Kanoon reproduction','https://indiankanoon.org/doc/1504026/?type=print','1994-09-28','Court record','Paras 23–30, retrieved lines 198–241','Editor of Ananda Vikatan imprisoned 4–6 April 1987 following cartoon privilege proceedings. Court found gross violations of natural justice and Articles 14/21; declared condemnation and punishment unconstitutional and void; awarded Rs 1,000 token compensation. It did not decide whether the cartoon itself breached privilege.','Editor’s own merits judgment. Distinct from Civil Liberties Council PIL dismissed for standing nine days earlier. Ruling concerns Speaker/Legislature action; not an individual conviction of MGR.')
src(9,'Jain Commission interim report: growth of Tamil militancy, Chapter 1, sections 11–15','Jain Commission; Tamil Nation reproduction','https://tamilnation.org/intframe/india/jaincommission/growth_of_tamil_militancy/ch1sec5','1997','Commission record','Paras 29–29.2, financial assistance; retrieved lines 34–68','Commission records 1987 aid of Rs 4 crore. Jayalalithaa, Karunanidhi and Guhan described aid reaching LTTE. State affidavit denied financing militant groups, saying Rs 3 crore went to Tamils’ Rehabilitation Organisation and Rs 1 crore to ROOTS on 30 April 1987 for affected Tamils.','Reproduced inquiry text on an advocacy archive; original report and underlying exhibits not inspected. Witness accounts and government response differ. Do not turn this into a conviction, a verified personal donation total, or an assertion that all aid was for arms.',origin='JAIN-INTERIM-1997')
src(10,'Contemporary Tamil Nadu since 1947 A.D., Unit 9','Alagappa University, Directorate of Distance Education','https://mis.alagappauniversity.ac.in/siteAdmin/dde-admin/uploads/3/__PG_M.A._History%20(English)_CONTEMPORARY%20TAMIL%20NADU%20SINCE%201947%20A.D-32132_3433.pdf',None,'Institutional research','Printed pp.115–122; PDF pp.124–131; lines 5848–6066','Party founded 17 October 1972 following DMK split. Party won Dindigul parliamentary by-election in 1973 and Coimbatore Assembly by-election in 1974; supported the 1975–77 Emergency. DMK government dismissed in 1976. First ministry sworn 30 June 1977; second 9 June 1980. In 1979 two AIADMK MPs joined Charan Singh ministry. Congress-DMK won 37/39 Tamil Nadu Lok Sabha seats in January 1980; AIADMK won two; MGR government dismissed, then AIADMK won 129 Assembly seats. Congress alliance won in 1984 despite his hospitalisation. Succession struggle followed death.','Teaching compilation visibly incorporates encyclopedic material and historical records; not independent of all web summaries. Current-party language is stale. Use exact ministry passages and bounded chronology, not sweeping causal claims. 1980 interruption is preserved.')
src(11,'The University: establishment history','Tamil Nadu Dr. M.G.R. Medical University','https://www.tnmgrmu.ac.in/the-university/',None,'Official record','Establishment paragraphs, lines 93–97','Committee considered a medical university from 1980; Tamil Nadu Act 37 of 1987 received presidential assent on 24 September 1987. University office established 12 July 1988 and functioning began July 1988. Act 39 of 1991 changed its name to Tamil Nadu Dr. M.G.R. Medical University.','Legislation during MGR’s government, operation after his death, and later naming are separate milestones.')
src(12,'Tamil University: institutional introduction','Tamil University, Thanjavur','https://www.tamiluniversity.ac.in/english/',None,'Official record','Homepage introduction','Tamil University established on 15 September 1981 at Thanjavur for advanced research in Tamil; statutory foundation Tamil Nadu Act 9 of 1982.','Institutional history supports establishment and purpose; no independent assessment of educational impact.')
src(13,'About Mother Teresa Women’s University','Mother Teresa Women’s University','https://motherteresawomenuniv.ac.in/about',None,'Official record','About University, lines 79–91; Act identification lines 106–108','Established in Kodaikanal in 1984 by Tamil Nadu Act 15; intended to serve women of all communities and promote education and employment prospects.','Creation and stated objectives are documented. Current campuses, enrolments and outcomes are not attributed to MGR personally.')
src(14,'TASMAC proactive RTI disclosures','Tamil Nadu State Marketing Corporation','https://tasmac.co.in/forms/rti-website-disclosure.pdf',None,'Official record','Indexed section I, organisation/functions','Index records incorporation on 23 May 1983 and exclusive wholesale privileges.','Original PDF returned 404; site moved and replacement timed out. Incorporation day and indexed May takeover are provisional; court S025 records June setup and July wholesale takeover.',status='Indexed passage only',method='web.run search extract; original failed')
src(15,'69 percent quota: Advantage TN','The New Indian Express archive','https://www.newindianexpress.com/amp/story/states/tamil-nadu/2010/Jul/14/69-percent-quota-advantage-tn-169690.html','2010-07-14','Journalism','Historical paragraph, retrieved line 120','MGR government imposed Rs 9,000 annual family-income ceiling for backward-class quota in 1979; withdrew it after 1980 Lok Sabha defeat and raised BC quota to 50%, taking combined reservation to 68%.','Archive update is 16 May 2012. Adjacent paragraph wrongly places DMK government in 1988; not adopted. Exact GO dates and later 69% chronology need original records. Political timing does not by itself prove sole motive.')
src(16,'Explained: relevance of the Vanniyar movement','Arun Janardhanan, Indian Express','https://indianexpress.com/article/explained/vanniyar-movement-in-tamil-nadu-relevance-today-7487807/','2021-09-04','Journalism','The movement; The 1987 deaths; Reservation granted','Vanniyar mobilisation sought separate reservation; road and rail blockades intensified in 1986–87. During 17–23 September 1987 agitation, at least 21 protesters died, mostly in police firing and also clashes with Scheduled Caste communities. No immediate settlement; later 1989 DMK government introduced 20% MBC allocation.','Retrospective reporting; not an inquiry report assigning individual responsibility. Do not recast all deaths as one verified police-firing count or credit later MBC reform to MGR.')
src(17,'Statistical Report: 1967 Madras Assembly election','Election Commission of India; Scribd reproduction','https://www.scribd.com/document/871117552/Madras-1967-1','1967','Official record','Constituency summary printed p.28; detailed result p.248; St. Thomas Mount, no.16','Poll 21 February 1967. MGR DMK 54,106; T.L. Raghupathy INC 26,432; K. Kasinathan BJS 613. Valid votes 81,151; polled 82,755; rejected 1,604; electors 108,071.','Original ECI route unavailable; identified reproduction inspected. State aggregate OCR has errors, so only mutually consistent constituency figures are used. Margin 27,674 is derived.',origin='ECI-MADRAS1967')
src(18,'St. Thomas Mount Assembly election history','Janadesh Online','https://janadeshonline.in/assembly/tamil-nadu/st-thomas-mount',None,'Dataset','1971 result table','MGR DMK 65,405; T.L. Raghupathy NCO 40,773; M. Varadarajan independent 850. Candidate-vote sum 107,028.','Secondary fallback; original 1971 return pending. Candidate total is used as valid-vote denominator, not ballots polled. No turnout inferred.')
src(19,'Aruppukkottai Assembly election history','Oneindia','https://www.oneindia.com/aruppukkottai-assembly-elections-tn-207/',None,'Dataset','1977 result table','MGR ADK 43,065; M. Muthuvel Servai JNP 13,687; A. Sivasamy INC 12,075; S.M. Bose DMK 5,415; remaining candidates 645,550,355,276,202,164,76,72. Candidate total 76,582.','Secondary fallback; original 1977 return pending. Displayed rounded percentages are not used; share recomputed from candidate totals. Historical ADK label normalized to AIADMK in workbook.')
src(20,'Madurai West Assembly constituency results','Result University','https://resultuniversity.com/election/maduraiwest-tamil-nadu-assembly-constituency',None,'Dataset','1980 table, retrieved lines 652–688','MGR ADK 57,019; Pon. Muthuramalingam DMK 35,953; A.C. Kamaraj 2,178; other candidates 130,124,123,119. Candidate total 95,646.','Secondary fallback; original 1980 return pending. Shares calculated from candidate total; turnout and displayed percentage labels not adopted.')
src(21,'Andipatti historical election results','Elections.in','https://www.elections.in/tamil-nadu/polling-stations/andipatti.html',None,'Dataset','1984 Assembly result, constituency 135','MGR ADK 60,510; Thangaraj alias Vallarasu DMK 28,026.','Winner/runner-up table only. Original return and full valid-vote total not inspected; vote share deliberately blank. Margin 32,484 is arithmetic, not independent corroboration.')
src(22,'Union Home Minister pays tribute to MGR on birth anniversary','Press Information Bureau, Ministry of Home Affairs','https://www.pib.gov.in/PressReleasePage.aspx?PRID=2215587&lang=1&reg=6','2026-01-17','Primary statement','Official tribute text','Amit Shah commemorated MGR’s cinema, public service and welfare contribution.','Primary evidence of present-day official remembrance, not neutral evidence of policy effectiveness or unanimity.')
src(23,'M G Ramachandran: artist biography','Cinemaazi, Indian Cinema Heritage Foundation','https://cinemaazi.com/people/m-g-ramchandran?ctr=31&filterBy=m&people=&search=',None,'Institutional research','Early cinema and political communication, lines 143–158','Theatre training; Congress connection before DMK; Sathi Leelavathi debut in 1936, Rajakumari in 1947 and Manthiri Kumari in 1950 as major films. Karunanidhi wrote Manthiri Kumari. MGR survived a 1967 shooting by M.R. Radha; hospital images accompanied public sympathy. Film persona and fan clubs supported campaigning. The new party claimed Annadurai’s ideals. The 1984 campaign used hospital video juxtaposed with Indira Gandhi’s assassination.','Cinema source contains political chronology errors (party renaming, Janaki succession, funeral date) and promotional superlatives. Those claims are rejected. Use bounded film/communication facts; shooting-case judgment not inspected.')
src(24,'Bharat Ratna notification No.18-Pres/88','President’s Secretariat, Gazette of India','https://www.padmaawards.gov.in/Document/pdf/Notifications/BharatRatna/1988BR.pdf','1988-01-26','Official record','PDF p.2, Bharat Ratna; Gazette cover dated 19 March 1988','Notification dated 26 January 1988 names M.G. Ramachandran for posthumous Bharat Ratna.','OCR of expanded name is imperfect. Notification date and later Gazette publication date are distinct; award year is secure.')
src(25,'Khoday Brewing & Distilling Industries v. State of Tamil Nadu','Madras High Court; Indian Kanoon reproduction','https://indiankanoon.org/doc/1575235/','1989-04-28','Court record','Paras 2,4–5; especially state counter-affidavit, retrieved lines 47–75','State stated TASMAC set up June 1983 and government took over wholesale liquor trade in July 1983. Arrack sales discontinued 1 January 1987. Government defended policy through revenue and supply objectives; 1988 procurement dispute occurred after MGR’s death.','Use as recorded government account of earlier institutional arrangements. Procurement allegations from parties are not findings of MGR’s personal corruption. Incorporation date differs from operational setup.')
src(26,'Civil Liberties Council v. Government of Tamil Nadu','Madras High Court; Indian Kanoon reproduction','https://indiankanoon.org/doc/1945665/?type=print','1994-09-19','Court record','Paras 6–15','Public-interest petition on the editor’s 1987 imprisonment was dismissed for standing; the editor had his own petitions.','Not a merits approval of imprisonment. S008 is the editor’s successful Full Bench case on 28 September 1994.')
src(27,'Mandal Commission report, Part I','Second Backward Classes Commission; NCBC archive','https://www.ncbc.nic.in/Writereaddata/Mandal%20Commission%20Report%20of%20the%201st%20Part%20English635228715105764974.pdf','1980','Official record','Indexed paras 2.59–2.62','Indexed passage describes increase of Tamil Nadu BC quota to 50% in 1980, plus 18% for SC/ST.','Full PDF timed out. Exact implementation day not treated as verified.',status='Indexed passage only')
src(28,'G.O.Ms.No.3078: Second Backward Classes Commission','Government of Tamil Nadu; TN Backward Classes Commission archive','https://www.bcc.tn.gov.in/ords/r/wstnbcc/107/files/static/v351/1982_GO_MS_3078-2%20%28TNBCC2%29-2.pdf','1982-12-13','Official record','Indexed references to GOs 72/73 of 1 February 1980','Potential primary route for quota chronology and Ambasankar Commission.','Original timed out; detailed order and findings not reviewed.',status='Retrieval failed')
src(29,'Statistical reports: historical Assembly election returns','Election Commission of India','https://www.eci.gov.in/statistical-reports',None,'Official record','Historical Assembly report index','Original constituency returns sought for 1967–1984.','Web and curl returned 406; CEO historical index did not expose these older reports. Labelled reproductions/secondary tables used; unresolved counts remain in queue.',status='Retrieval failed')
src(30,'K. Rajendran v. State of Tamil Nadu','Supreme Court; SooperKanoon reproduction','https://sooperkanoon.com/case/640091/k-rajendran-vs-state-tamil','1982-04-15','Court record','Indexed judgment on village-office abolition','Potential evidence for 1980 village-administration reform and constitutional challenge.','Full text unavailable in attempted route. Not used to certify a reform outcome or final disposition.',status='Indexed passage only')
src(31,'Training report: community nutrition, June 2021','National Institute of Disaster Management','https://nidm.gov.in/pdf/trgReports/2021/June/Report_21-23June2021aw.pdf','2021-06','Official record','Indexed slide: Genesis in Tamilnadu','Slide describes earlier school meals and Kamaraj’s 1956 programme, with MGR expansion in 1982.','Indexed slide only; full passage retrieval failed. Exact early municipal chronology not adopted.',status='Indexed passage only')
src(32,'Noon Meal Programme: history and objectives','Tiruvarur district, Government of Tamil Nadu','https://tiruvarur.nic.in/departments/noon-meal-programme/',None,'Official record','History and objective paragraphs','School feeding in Madras Corporation predated MGR by decades; MGR programme covered rural preschool and primary-school ages.','Its July urban-extension wording conflicts with S003/S004 September date; rejected. Use solely to establish pre-1982 antecedents, not exact first-origin date.')

def failed(n,sid,url,result):
    retrievals.append({'id':f'F{n:03d}','source_id':f'S{sid:03d}','url_or_query':url,'access_date':ASOF,'route':'Canonical or alternate attempt','access_status':'Retrieval failed','origin_id':sources[sid-1]['Origin ID'],'locator':'No usable passage','passage_paraphrase':'','method':'web.run / curl','result':result,'next_action':'Stopped; use inspected fallback or await a better route.'})
